import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Widget SDK, gateway and overlay boundaries","description":"","frontmatter":{"title":"Widget SDK, gateway and overlay boundaries","docId":"developer.overlays","translationKey":"developer.overlays","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","order":170},"headers":[],"relativePath":"en/developer/overlays.md","filePath":"en/developer/overlays.md","lastUpdated":1794611623000}'),n={name:"en/developer/overlays.md"};function r(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">Widget SDK, gateway and overlay boundaries <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;Widget SDK, gateway and overlay boundaries {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Build a widget that shares rendering between local preview and OBS output. Use the installed Vue toolchain and understand <a href="./events.html">events</a>. Local preview needs no gateway or account credential. Live widget output requires the separately installed event-gateway plugin and its widget-scoped credential.</p><h2 id="add-a-template" tabindex="-1">Add a template <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;Add a template {#add-a-template}&quot;">​</a></h2><ol><li>Define a renderer inside <code>WidgetStage</code>; size it relative to its parent rather than the browser viewport.</li><li>Use <code>defineWidget</code> from <code>src/widgets/sdk/template.ts</code>. Supply its schema, fresh sample envelopes and <code>create(search, clock)</code> factory.</li><li>Return a controller implementing <code>handleEnvelope</code>, <code>clear</code> and <code>dispose</code>, plus rendering. Use the supplied clock so previews can hold samples and tests can advance time.</li><li>Register it in <code>sdk/templates.ts</code>, then add the standalone entry, build configuration, gateway route allowlist and packaging entry. Registration alone does not expose a public URL.</li><li>Use the same <code>WidgetHost.vue</code> in the editor and standalone bundle; do not embed gateway HTML for a local preview.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>Keep text tokens, design defaults and editable fields in the template schema. Designs serialize as JSON and copied widget URLs carry a validated snapshot; a later save requires copying an updated URL into OBS.</p><h2 id="gateway-protocol" tabindex="-1">Gateway protocol <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;Gateway protocol {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> owns authentication, subscriptions, heartbeat, reconnect and gap reporting. Widgets consume canonical domain envelopes, not TikTok directly. The widget endpoint is <code>/ws/widgets</code>; it differs from the full external gateway client surface. Parse envelopes through the shared parser and preserve credential boundaries instead of passing a full gateway token through the main WebView.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Built-in local previews and the widget SDK are implemented. Cloud overlay editing and <code>cloud-overlay</code> source code exist, but real OBS validation, artwork/live-source coverage and package application retain limits. Overlay Changes is an unmerged follow-up. Rankings remains hidden in normal application navigation even though ranking widget code exists.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For a blank local preview, inspect controller lifetime, schema defaults and stage sizing before weakening origin policy. For live output, inspect gateway health, widget credential and explicit gaps. A headless Chromium test does not prove OBS Browser Source acceptance. The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">Widget SDK</a> and shared protocol tests are the current implementation references.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>The independent widget unit suite uses fixtures; the real-gateway Chromium suite needs built widget assets and the external plugin checkout selected by <code>TIKTOOLS_PLUGINS_REPO</code>. It skips when that source is missing: report a skip explicitly. Run <code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> for that separate boundary. Then verify actual OBS Browser Source, widget credential, event delivery and recovery with real LIVE input; headless Chromium does not establish OBS/native acceptance.</p>`,15)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
